#include <bits/stdc++.h>
using namespace std;
int MOD;
int mpow(int x, int n) {
	int res = 1;
	while (n) {
		if (n & 1) res = 1LL * res * x % MOD;
		x = 1LL * x * x % MOD;
		n >>= 1;
	}
	return res;
}
const int N = 3e5 + 5;
unsigned long long dp[27][N];
int rf[N], f[N];
int permute(int n, int m) {
	return 1LL * f[n] * rf[n - m] % MOD;
}
int main() {
	int n, K;
	scanf("%d%d%d", &n, &K, &MOD);
	if (n & 1) {
		printf("%d\n", mpow(K, n));
		return 0;
	}
	f[0] = 1;
	for (int i = 1; i <= n; ++ i) f[i] = 1LL * f[i - 1] * i % MOD;
	rf[n] = mpow(f[n], MOD - 2);
	for (int i = n - 1; i >= 0; -- i) rf[i] = 1LL * rf[i + 1] * (i + 1) % MOD;
	dp[0][0] = 1;
	for (int k = 0; k < K; ++ k) {
		for (int i = 1; i <= n; ++ i) {
			if ((i & n) != i) continue;
			int cnt = 0;
			unsigned long long &res = dp[k + 1][i];
			int hb = (1 << (31 - __builtin_clz(i)));
			for (int j = i - hb; j >= 0; j = (j - 1) & i) {
				int jj = j + hb;
				res += dp[k][i ^ jj] * rf[jj];
				if (cnt ++ == 17) {
					res %= MOD;
					cnt = 0;
				}
				if (j == 0) break;
			}
			res %= MOD;
		}
	}
	int ans = 0;
	for (int i = 0; i <= K; ++ i) (ans += 1LL * f[n] * dp[i][n] % MOD * permute(K, i) % MOD) %= MOD;
	printf("%d\n", (mpow(K, n) + MOD - ans) % MOD);
}


